var t=[{title:`Helhetsbilden`,text:`Träning använder energi, och mat ger det du behöver för att träna, återhämta dig och bygga vävnad. En varierad kost innehåller vanligtvis proteinrika livsmedel, kolhydratrika livsmedel, frukt, grönsaker och fettkällor. Mycket restriktivt ätande kan hålla tillbaka din prestation och återhämtning även när dina pass är väl utformade.`},{title:`Protein och muskler`,text:`Protein ger aminosyror som din kropp använder för att underhålla vävnad och anpassa muskler. Forskning om tränande vuxna anger ofta ungefär 1,4–2,0 gram protein per kilogram kroppsvikt och dag som ett evidensbaserat intervall. Behoven skiljer sig med ålder, träning och personliga omständigheter, och du behöver inte räkna ut den siffran.`},{title:`Kolhydrater och fetter`,text:`Kolhydrater driver upprepade hårda insatser och uthållighetspass genom att upprätthålla muskelglykogen. Kostfett ger essentiella fettsyror och hjälper dig att ta upp vissa vitaminer. Detaljerade strategier för idrottsnutrition spelar större roll när din träningsvolym ökar. Som nybörjare, fokusera först på regelbundna, balanserade måltider.`},{title:`Exempel`,text:`Om du styrketränar tre dagar i veckan kan du bygga måltider kring bönor, fisk, ägg eller en annan proteinkälla, lägga till spannmål eller potatis för energi och inkludera grönsaker och frukt. Det du äter under veckan betyder mer än att dricka en viss shake direkt efter varje set.`},{title:`När du ska söka experthjälp`,text:`Om du har ett medicinskt tillstånd, oro kring ätande eller ett specialiserat prestationsmål, tala med en legitimerad dietist eller en vårdgivare. TrainUp ger inga individuella kalorimål, makrospårning eller måltidsplaner för viktminskning.`}];var n=[{label:`ISSN:s ställningstagande: protein och träning`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC5477153/`},{label:`ACSM:s ställningstagande 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var a={sections:t,sources:n};export{a as default,t as sections,n as sources};